import math


def law(input_data: list[dict[str, float]], group: str) -> list[dict[str, float]]:
    """
    Predicts brier_score based on flops/log_flops according to a scaling law.

    Formula: brier_score = a + b * log10(flops) + c * log10(flops)^2

    Coefficients are group-specific, fitted via least squares on the training data.
    """
    COEFFS = {
        "abstract_narrative_understanding": {
            "a": -0.543140714074,
            "b": 0.184726990056,
            "c": -0.001002095719,
        },
        "analogical_similarity": {
            "a": -0.540575053774,
            "b": 0.027911287483,
            "c": -0.019175879673,
        },
        "arc": {
            "a": -0.107112232715,
            "b": 0.117619490399,
            "c": -0.036868206394,
        },
        "arithmetic": {
            "a": -0.247532677712,
            "b": 0.235370097975,
            "c": -0.129978149629,
        },
        "conceptual_combinations": {
            "a": -0.409345543131,
            "b": 0.096925955229,
            "c": -0.071483567065,
        },
        "hellaswag": {
            "a": -0.067196861546,
            "b": 0.098051454349,
            "c": -0.033670645756,
        },
        "hindu_knowledge": {
            "a": -0.410317419378,
            "b": -0.031143510555,
            "c": -0.034402388960,
        },
        "mmlu": {
            "a": -0.480364650220,
            "b": -0.062970434888,
            "c": 0.011476264281,
        },
        "parsinlu_qa_mc": {
            "a": -0.434950718068,
            "b": 0.098905837326,
            "c": -0.056567395374,
        },
    }

    if group not in COEFFS:
        raise ValueError(f"Unknown group: {group}")

    c = COEFFS[group]
    results = []

    for point in input_data:
        if "log_flops" in point:
            x = point["log_flops"]
        elif "flops" in point:
            x = math.log10(point["flops"])
        else:
            raise ValueError("Input must contain 'flops' or 'log_flops'")

        brier = c["a"] + c["b"] * x + c["c"] * x * x
        results.append({"brier_score": brier})

    return results

